var t=Math.max(0,time);
var s;
if(t<=1){s=100+5*t+7*t*t;}else{var d=Math.min(t-1,0.7);var x=d/0.7;s=112+19*d+30*x*x+920*Math.pow(x,5);}
[s,s];

// Only the last four frames of the fast exit fade.
var u=Math.max(0,Math.min(1,(time-47/30)/(4/30)));
100*(1-u*u);

var u = Math.max(0, Math.min(1, (time-key(1).time)/(key(2).time-key(1).time)));
var e = 1-Math.pow(1-u,3);
var a = (-124-20*e)*Math.PI/180;
[675+358*Math.cos(a),494+358*Math.sin(a)];
